<?php
namespace App\Services\Analysis\Markets;use App\DTOs\Football\{MarketAnalysisResult,MatchEvidence};use App\Enums\MarketType;use App\Services\Analysis\MarketStatusResolver;final class Under45Analyser{public function __construct(private MarketStatusResolver $status){}public function analyse(MatchEvidence $e):MarketAnalysisResult{$p=[];$n=[];$q=min(100,45+$e->sampleSize*5);$score=(int)round(96-($e->over45Rate*55));if($e->over45Rate<=.10)$p[]='Five-or-more-goal matches are rare in the recent samples.';if($e->over45Rate>=.20){$n[]='Recent 5+ goal frequency is too high for a conservative under.';$score-=10;}if($e->homeTeamOver45Rate>=.30||$e->awayTeamOver45Rate>=.30){$n[]='At least one team has repeated recent 5+ goal matches.';$score-=10;}if($e->highVarianceCompetition){$n[]='High-variance competition.';$score-=8;$q-=10;}if($e->rotationRisk){$n[]='Rotation can increase match volatility.';$score-=5;}$score=max(0,min(100,$score));return new MarketAnalysisResult(MarketType::UNDER_45,'Under 4.5 Match Goals',$score,max(0,$q),$this->status->resolve($score,$q),$p,$n,$n[0]??'An early red card or defensive collapse can create a 5+ goal match.');}}
